INSERT INTO `cat_action_lines` VALUES (1, 'Impulsar un nuevo esquema de relaciones entre los diversos actores sociales y gubernamentales para lograr un desarrollo económico, social e institucional, promoviendo un equilibrio entre el Estado y la sociedad civil.', 1, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (2, 'Impulsar la participación ciudadana como un método transversal de elaboración de políticas públicas y toma de decisiones fundamentales para el Estado.', 2, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (3, 'Inscribir, certificar y dar publicidad a los hechos y actos relacionados con el estado civil de los ciudadanos Campechanos, instituyendo mecanismos de forma incluyente que garanticen la certeza jurídica al derecho a la identidad', 3, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (4, 'Revisar la legalidad de los actos jurídicos que se realizan en el desarrollo de la administración pública Estatal', 4, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (5, 'Analizar y emitir opiniones técnicas sobre los proyectos de convenios y contratos a celebrar entre el Estado y la Federación, entidades federativas y municipios así como en la revisión y elaboración de los proyectos de iniciativas de ley, y todas aquellas adecuaciones al marco normativo estatal.', 5, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (6, 'Proteger los intereses del Estado en materia jurídica en procesos constitucionales, contenciosos o no contenciosos', 6, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (7, 'Coordinar con los municipios del Estado en materia jurídica en procesos constitucionales que afecte los intereses del mismo.', 7, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (8, 'Establecer políticas integrales para el desarrollo social y económico, diálogo permanente para garantizar el libre ejercicio de la libertad de culto y asociaciones religiosas, así como la mediación de conflictos que otorguen la legalidad en la tenencia de la tierra.', 8, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (9, 'Inscribir, certificar y dar publicidad a los actos jurídicos relacionados con el patrimonio inmobiliario, mercantil y de sociedades en general, susceptibles de inscribirse en el Registro Público de la Propiedad y de Comercio del Estado', 9, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (10, 'Publicar, difundir y expedir leyes, decretos, reglamentos, acuerdos, circulares, órdenes y demás actos emitidos por las autoridades competentes para efecto de dotarlos de legalidad y vigencia.', 10, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (11, 'Dotar de certeza legal a los actos jurídicos de particulares, mediante la regulación de la fe pública.', 11, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (12, 'Implementar acciones de cultura demográfica y análisis sociodemográficos que ayuden a las diversas instancias gubernamentales y coadyuven al mejoramiento de las condiciones de vida en el Estado', 12, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (13, 'Identificar las demandas sociales y económicas derivadas del cambio en la estructura por edad y sexo de la población para contribuir a la creación de políticas públicas que favorezcan el desarrollo, la igualdad y el bienestar social de toda la población.', 13, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (14, 'Incrementar la cultura demográfica orientada a concientizar, sobre el origen, causas y consecuencias de los fenómenos demográficos que impactan el curso de vida en lo individual y social de la población en el Estado.', 14, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (15, 'Dar cursos de capacitación a los servidores públicos de los gobiernos municipales, para el fortalecimiento de sus capacidades y que les permita incrementar la profesionalización para la toma de decisiones.', 1, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (16, 'Dar asesoría técnica a los gobiernos municipales en temas relacionados a sus funciones para el cumplimento de sus objetivos de desarrollo municipal', 2, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (17, 'Promover la aplicación de instrumentos para el monitoreo de desempeño municipal, para llevar a cabo una gestión eficiente y eficaz en la implementación de sus capacidades institucionales. ', 3, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (18, 'Detectar necesidades en cuestión de cobertura abierta, calidad de señal y posibilidad de alianzas municipales con el fin de tener un flujo bidireccional de información y entretenimiento con el pueblo de Campeche', 1, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (19, 'Privilegiar el interés del pueblo de Campeche por encima de cualquier otro, devolviéndole la pantalla y el micrófono a la gente, haciéndolas partícipes de la construcción y mejora de su entorno, logrando que se involucren en hacer suyo el espacio público para la responsabilidad compartida con el futuro de nuestro estado', 2, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (20, 'Establecer los mecanismos y estrategias de comunicación social para acercar al gobierno a todos y todas.', 3, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (21, 'Impulsar el sentido de pertenencia y responsabilidad con el pueblo de Campeche a través de campañas institucionales.', 4, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (22, 'Generar diversos programas de interés turístico, cultural y educativo sin perder el rasgo de entretenimiento que permita captar a nuevas audiencias buscando ser el tópico común en el discurso de la gente.', 5, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (23, 'Visibilizar la discapacidad desde un punto de vista empático, de respeto y generar el discurso de verdadera inclusión mientras, incidimos en la concientización de nuestro actuar cotidiano y la apertura de nuestro espacio público a un entorno amable con quienes requieren de un sistema diferente.', 6, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (24, 'Ser ejemplo de respeto, tolerancia e inclusión, buscando que sea el actuar diario detrás de cámara, los podcasts, la transmisión en pantalla y en radio, lo que influye e impacta en la mejora de nuestra sociedad a través de la exposición del modelo conductual.', 7, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (25, 'Identificar, valorar y transferir los documentos de los archivos de concentración de las dependencias que cumplan con los criterios de relevancia para la memoria nacional, regional o local de carácter público.', 1, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (26, 'Catalogar, digitalizar, conservar y restaurar el acervo documental histórico, de acuerdo a la normatividad y estándares nacionales e internacionales.', 2, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (27, 'Desarrollar y ejecutar procesos de homologación, asesoría, capacitación, cooperación y valoración documental en materia archivística y de Patrimonio Documental Histórico para las Unidades Coordinadoras de Archivo del Poder Ejecutivo del Estado', 3, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (28, 'Conciliar, agilizar la tramitación de asuntos en materia laboral para solucionar los conflictos que se producen en las relaciones obrero-patronales.', 1, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (29, 'Privilegiar la conciliación en asuntos Individuales y colectivos en las autoridades jurisdiccionales laborales y en la Procuraduría de la Defensa del Trabajo.', 2, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (30, 'Reforzar las inspecciones ordinarias y extraordinarias en los centros de trabajo en el Estado, para vigilar el respeto de la normatividad laboral.', 3, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (31, 'Garantizar los Derechos de los Adolescentes en edad permitida para trabajar.  ', 4, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (32, 'Mejorar la conciliación, procuración e impartición de justicia laboral garantizando la certeza jurídica para todas las partes en las resoluciones laborales.', 5, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (33, 'Fortalecer el contacto personal y directo con los trabajadores y sus empleadores para brindar un servicio público de conciliación laboral imparcial, sencillo, eficiente, eficaz y proponer soluciones a sus problemas laborales', 6, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (34, 'Celebrar convenios de conciliación entre las partes o expedir constancias de no conciliación.', 7, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (35, 'Difundir en todo el Estado en forma clara y sencilla la utilidad y ventajas de la conciliación imparcial para el respeto a los derechos adquiridos por la persona trabajadora.', 8, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (36, 'Acercar el servicio de conciliación laboral a la población trabajadora más vulnerable.', 9, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (37, 'Sistematizar y bancarizar la recaudación.', 1, 6, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (38, 'Simplificar el esquema impositivo que facilite a los contribuyentes el cumplimiento de sus obligaciones fiscales.', 2, 6, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (39, 'Revisar y actualizar el marco jurídico en materia hacendaria y alinear a los objetivos del Plan Estatal de Desarrollo ', 3, 6, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (40, 'Garantizar la debida defensa legal del Estado en materia hacendaria', 4, 6, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (41, 'Elaborar convenios y acuerdos con la federación, entidades estatales y municipales, cuidando legalmente los intereses del Poder Ejecutivo del Estado, que permitan la recepción, administración y distribución de los recursos financieros.', 5, 6, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (42, 'Instrumentar medidas de austeridad para orientar el gasto público y mejorar los controles financieros asociados al ejercicio de los programas presupuestarios, así como de los mecanismos de administración establecidos para el cumplimiento de las obligaciones derivadas de los financiamientos', 1, 7, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (43, 'Administrar y ejecutar un Presupuesto Basado en Resultados con base en los objetivos, estrategias y líneas de acción del Plan Estatal de Desarrollo.', 2, 7, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (44, 'Supervisar el uso de los fondos federales destinados a inversión, en coordinación con las entidades ejecutoras y garantizar que estén alineados con los objetivos del Plan Estatal de Desarrollo.', 3, 7, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (45, 'Evaluar los programas y proyectos de inversión pública para un uso eficaz y eficiente del Presupuesto de Egresos.', 4, 7, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (46, 'Reforzar la gestión de los recursos humanos, materiales, patrimoniales y de servicios de acorde a las necesidades de los Organismos Centralizados y Entidades Paraestatales del Poder Ejecutivo de la Administración Pública del Estado de Campeche.', 1, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (47, 'Implementar acciones que mejoren la administración y manejo de recursos, con estándares de calidad, a fin de resolver las necesidades de manera efectiva.', 2, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (48, 'Ejecutar las contrataciones y licitaciones de compra pública mediante los criterios de competitividad con un sistema de disciplina presupuestal los cuales se administran bajo los criterios de eficiencia, eficacia, economía, transparencia y honradez', 3, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (49, 'Reforzar la gestión de los recursos humanos mediante un sistema de selección, capacitación y evaluación profesional de capital humano, que permita una adecuada competitividad y efectividad laboral atendiendo las necesidades de los Organismos Centralizados y Entidades Paraestatales', 4, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (50, 'Diseñar mecanismos que fortalezcan la suficiencia financiera de la reserva de pensiones, así como los Servicios de Seguridad Social para los Trabajadores y Pensionados del Estado.', 5, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (51, 'Administrar los bienes que sean destinados a favor del Estado en razón de procedimientos administrativos o jurisdiccionales que hayan quedado firmes y los asegurados en materia de extinción de dominio; proceder a dar destino favorable a los bienes que hayan sido otorgados a favor del Estado que permitan el fortalecimiento del desarrollo estatal.', 6, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (52, 'Vigilar la aplicación de los recursos públicos mediante evaluaciones del cumplimiento de los objetivos y metas con base en indicadores estratégicos y de gestión gubernamental, con la finalidad de que la programación del presupuesto del gasto público sea transparente y eficiente.', 1, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (53, 'Coordinar y dar seguimiento a las evaluaciones que realizan las Dependencias y Entidades de la Administración Pública Estatal que permita conocer los resultados de la aplicación de los recursos públicos; dando seguimiento a los Aspectos Susceptibles de Mejora.', 2, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (54, 'Establecer normas, lineamientos, criterios, guías y procedimientos que regulen los procesos de evaluación de programas de la Administración Pública Estatal.', 3, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (55, 'Eficientar y dar seguimiento a los procedimientos de auditoría y fiscalización, a fin de mitigar los riesgos de corrupción que lesionen las finanzas y los recursos públicos del Estado.', 4, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (56, 'Verificar y dar seguimiento al cumplimiento de las normas y disposiciones que regulan todos los procesos y procedimientos de la Administración Pública Estatal.', 5, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (57, 'Supervisar, coordinar y vigilar el Sistema de Control Interno Institucional en las Dependencias, Organismos Centralizados y Entidades Paraestatales de la Administración Pública Estatal.', 6, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (58, 'Vigilar que los procesos de licitación y adjudicación de contratos se realicen cumpliendo las disposiciones legales correspondientes, a fin de asegurar su legalidad y que el ejercicio del gasto público sea racionalizado, transparente, eficiente y eficaz para una rendición de cuentas con enfoque a resultados.', 7, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (59, 'Impulsar acciones que propicien la transparencia y rendición de cuentas en la gestión pública; así como garantizar al ciudadano el acceso oportuno a información pública de calidad', 8, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (60, 'Coordinar y dar seguimiento al cumplimiento de las normas y disposiciones que establecen la Ley General de Contabilidad Gubernamental y las Leyes de Disciplina Financiera Federal y Estatal. ', 9, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (61, 'Asegurar el cumplimiento de la Ley de Transparencia y Acceso a la Información Pública del Estado de Campeche, para reforzar la confianza y credibilidad de la ciudadanía en el quehacer gubernamental.', 10, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (62, 'Administrar y mantener actualizado el portal del Registro Estatal de Regulaciones.', 1, 10, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
