INSERT INTO `cat_action_lines` VALUES (64, 'Realizar acciones que induzcan entre las niñas, niños y adolescentes de todo el Estado valores y principios éticos.', 1, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (65, 'Instaurar programas dirigidos a la ciudadanía que fomenten la ética y el combate a la corrupción', 2, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (66, 'Coordinar, dar seguimiento y evaluar las acciones que realicen las Dependencias y Entidades en materia de ética, integridad pública y prevención de conflictos de intereses; promoviendo con ello entre las y los servidores públicos una cultura de combate a la corrupción', 3, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (67, 'Asumir la representación legal ante la autoridad competente con el carácter de asesor jurídico de la parte ofendida de los delitos por hechos de corrupción, cometidos en agravio de las Secretarías y Dependencias de la Administración Pública Estatal.', 4, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (68, 'Realizar acciones que incentiven la participación activa y consciente de los distintos sectores de la sociedad fomentando los principios éticos y valores a través de capacitaciones con el fin de que la ciudadanía participe activamente en la vigilancia de la correcta aplicación de los recursos públicos y el combate a la corrupción', 5, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (69, 'Colaborar con los integrantes del Comité Coordinador del Sistema Anticorrupción del Estado de Campeche en la prevención, investigación y sanción de las faltas administrativas y los hechos de corrupción, además de ejecutar la Política Estatal Anticorrupción.', 6, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
