INSERT INTO `cat_action_lines` VALUES (72, 'Presentar las denuncias de carácter penal ante la Fiscalía Especializada en Combate a la Corrupción del Estado y demás autoridades competentes, por hechos derivados de la detección de conductas ilícitas o actos de corrupción con motivo del ejercicio del control interno y de las actividades de auditoría y fiscalización que se realicen', 9, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
