INSERT INTO `cat_action_lines` VALUES (77, 'Establecer mecanismos de coordinación y colaboración interinstitucional e intergubernamental bajo el marco del Sistema Estatal de Planeación Democrática', 1, 12, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (78, 'Coordinar los planes y programas sectoriales, institucionales y especiales dentro de una contribución efectiva a los objetivos del desarrollo estatal', 2, 12, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
