INSERT INTO `cat_action_lines` VALUES (80, 'Fomentar mecanismos de monitoreo, seguimiento y evaluación continua sobre el cumplimiento de objetivos y metas en planes y programas que contribuyan a la mejor toma de decisiones ', 4, 12, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (81, 'Brindar asesoría y capacitación a los servidores públicos del gobierno estatal y municipal, en matería de planeación y evaluación de los instrumentos de política pública', 5, 12, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (82, 'Procurar la alineación del programa anual de inversión pública, así como orientar sus recursos de manera eficiente, al cumplimiento de los objetivos estrátegicos planteados en el Plan Estatal de Desarrollo', 6, 12, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
