INSERT INTO `cat_action_lines` VALUES (84, 'Fomentar, procurar e incentivar acciones, programas y/o proyectos de intercambio y colaboración con actores internacionales', 8, 12, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (85, 'Implementar esquemas de mejores prácticas para la modernización de la Administración Pública Estatal.', 1, 13, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
