INSERT INTO `cat_action_lines` VALUES (87, 'Implementar mecanismos y herramientas de mejora regulatoria en virtud que los beneficios de las regulaciones, los trámites y los servicios sean superiores a sus costos.', 1, 14, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
