INSERT INTO `cat_action_lines` VALUES (91, 'Instalar infraestructura digital pública para facilitar el cumplimiento gubernamental de las obligaciones de transparencia y consulta de los ciudadanos', 1, 16, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (92, 'Digitalizar los trámites para hacer más eficiente y transparente la gestión pública', 2, 16, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
