INSERT INTO `cat_action_lines` VALUES (94, 'Regular el transporte de personas, bienes y servicios, priorizando la sostenibilidad,  accesibilidad y eficiencia económica, con el objetivo de garantizar la protección de los derechos de todos los usuarios, incluidas las personas con discapacidad o necesidades especiales.', 1, 17, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (95, 'Realizar estudios de factibilidad ambiental, jurídica, técnica y financiera para establecer los fundamentos que impulsen la mejora en la gestión y operación del transporte público', 2, 17, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (96, 'Elaborar programas de capacitación dirigidos a concesionarios y permisionarios, abordando aspectos técnicos, de recursos humanos y administrativos, con el propósito de asegurar el cumplimiento de las normativas y aplicar medidas de sanción cuando corresponda', 3, 17, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (97, 'Realizar estudios para establecer las especificaciones técnicas de las unidades del transporte público mediante inspección y verificación.', 4, 17, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (98, 'Evaluar y optimizar el rendimiento del transporte público según las necesidades y oportunidades identificadas en la administración y gestión institucional', 5, 17, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (99, 'Impulsar la armonización del marco normativo estatal en materia de derechos humanos, en apego a lo que mandata la reforma constitucional', 1, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (100, 'Difundir y divulgar qué son los derechos humanos, para que las personas conozcan cómo ejercer y defender sus derechos', 2, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (101, 'Diseñar y desarrollar programas de capacitación y sensibilización en materia de derechos humanos para el personal de la administración pública estatal y la sociedad civil organizada', 3, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (102, 'Dar seguimiento a quejas, recomendaciones, propuestas de amigable composición, medidas de protección, entre otras; emanadas de los organismos protectores de derechos humanos, así como de la Secretaría de Gobernación', 4, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (103, 'Profesionalizar y especializar a la policía en las diversas áreas de prevención y atención de faltas administrativas y posibles hechos delictivos.', 1, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (104, 'Dignificar a los policías mediante incentivos, reconocimientos, proyectos de vivienda, complementación e incremento salarial y otorgamiento de grados.', 2, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (105, 'Implementar acciones para apoyar en las afectaciones psicológicas que sufran los elementos policíacos en el desempeño de sus funciones.', 3, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (106, 'Proponer un Modelo Integral de Protección y Seguridad Ciudadana, que contemple la capacitación especializada, el uso de tecnología de vanguardia y la infraestructura para el desempeño policial.', 4, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (107, 'Consolidar la generación de bases de datos y el análisis de información como herramienta de inteligencia, investigación y la correcta distribución del estado de fuerza y equipamiento para el combate a la delincuencia y la atención a las faltas administrativas.', 5, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (108, 'Fortalecer el servicio de atención de llamadas de emergencia 9-1-1 y emprender acciones para concientizar sobre el uso correcto del mismo.', 6, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (109, 'Mejorar la infraestructura de las instituciones de seguridad, así como dotarlas de equipo y tecnología, priorizando siempre las necesidades de la operatividad, el personal operativo y administrativo.', 7, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (110, 'Instalar, mantener, operar y ampliar el sistema de videovigilancia urbana que permita la creación de un sistema integral que tenga cobertura en todo el estado de Campeche.', 8, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (111, 'Impulsar el programa REPUVE en el Estado, como mecanismo de seguridad y certeza jurídica para los propietarios de vehículos, a través del trámite de inscripción o actualización vehicular al programa', 9, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (112, 'Mejorar la tecnología de los puntos de monitoreo inteligente, monitoreo vehicular y arcos carreteros instalados, así como ampliar su cobertura en el territorio estatal.', 10, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (113, 'Supervisar la actuación policial e investigar las posibles faltas al régimen disciplinario, a fin de transparentar el desempeño del servicio e incrementar la confianza ciudadana.', 11, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (114, 'Impulsar la implementación de un sistema homologado enfocado al desarrollo, estabilidad y seguridad personal de los integrantes de las instituciones policiales.', 1, 20, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (115, 'Promover la acreditación y certificación del personal docente e instructores para seguridad.', 2, 20, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (116, 'Homologar y jerarquizar los contenidos de formación continua para que complementen la formación inicial y fortalezcan las competencias de los elementos de las instituciones de seguridad, de procuración de justicia y del sistema penitenciario.', 3, 20, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
