INSERT INTO `cat_action_lines` VALUES (197, 'Promover campañas informativas para sensibilizar y brindar atención sobre salud sexual, prevención del suicidio, diversidad, igualdad sustantiva y no discriminación, dirigidas a toda la comunidad educativa, con el fin de fomentar un ambiente inclusivo, respetuoso y seguro en los entornos educativos.', 12, 34, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (198, 'Ampliar y fortalecer la excelencia en la oferta institucional de los centros educativos de educación básica, media superior y superior en el estado, para asegurar que los estudiantes adquieran competencias integrales para su desarrollo en todos los ámbitos', 1, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (199, 'Promover la actualización de planes y programas de estudio, para que incorporar elementos y enfoques de la Nueva Escuela Mexicana, basados en valores y competencias que contribuyan al desarrollo y bienestar de los habitantes del Estado.', 2, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (200, 'Ampliar la oferta de programas de posgrado y de cuerpos académicos que impacten en la transformación social, fomentando la creación y consolidación de grupos de investigación científica y desarrollo tecnológico en áreas estratégicas para el progreso del Estado.', 3, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (201, 'Incorporar la educación ambiental en los planes educativos formales para promover la preservación del medio ambiente y el reconocimiento del valor de la diversidad natural y cultural de la región.', 4, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (202, 'Impulsar la formación, actualización y desarrollo profesional de los docentes y directivos de todos los niveles educativos, mediante programas y acciones que promuevan la mejora continua de sus competencias pedagógicas, técnicas y de liderazgo.', 5, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (203, 'Promover acciones y programas para el desarrollo socioemocional de estudiantes y docentes, fomentando su bienestar emocional y habilidades para manejar emociones y relaciones interpersonales de manera adecuada.', 6, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (204, 'Establecer vínculos entre instituciones educativas y los sectores productivo y social para facilitar la inclusión laboral de estudiantes y promover el emprendimiento social.', 7, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (205, 'Garantizar la capacitación y certificación continua de los maestros, fomentando el intercambio de experiencias entre docentes y estudiantes con instituciones académicas e investigativas nacionales e internacionales.', 8, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (206, 'Ofrecer cursos intensivos de inglés y maya para estudiantes y docentes, con el fin de fortalecer las habilidades lingüísticas en ambos idiomas y promover la diversidad cultural y lingüística en la comunidad educativa.', 9, 35, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (207, 'Impulsar el desarrollo de competencias científicas, profesionales y técnicas en estudiantes desde las instituciones educativas estatales, con el propósito de fomentar la creación de iniciativas y proyectos sociales y soluciones sostenibles en beneficio de personas, familias y comunidades en condición de vulnerabilidad.', 1, 36, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (208, 'Ofrecer cursos de capacitación sobre desarrollo humano, derechos humanos, igualdad y no discriminación para la población en general, fortaleciendo sus capacidades para generar oportunidades de desarrollo personal y colectivo', 2, 36, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (209, 'Fortalecer los programas de formación para el trabajo con enfoque en actividades que incrementen las capacidades de la población, permitiéndoles mejorar sus condiciones de bienestar y calidad de vida mediante habilidades y competencias laborales relevantes y demandadas en el mercado.', 3, 36, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (210, 'Promover alianzas público-privadas para fomentar la creación de empresas y competencias emprendedoras con enfoque social, proporcionando recursos, conocimientos y oportunidades para generar impacto positivo y en la comunidad y la sociedad en general.', 4, 36, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (211, 'Fomentar el diseño e implementación de programas que impulsen el progreso científico, tecnológico y técnico en las regiones del Estado, aprovechando sus vocaciones, cultura y recursos naturales para promover el desarrollo sostenible y el bienestar de la población.', 5, 36, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (212, 'Alinear los programas educativos y de formación para el trabajo, con las necesidades de desarrollo del Estado, priorizando actividades que potencien las capacidades de la población, con miras a mejorar su bienestar y calidad de vida a través de habilidades y competencias laborales demandadas en el mercado y considerando la vocación productiva de la región.', 6, 36, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (213, 'Promover espacios para la innovación y el desarrollo de proyectos donde las y los estudiantes de la región puedan aplicar sus conocimientos y ofrecer asesoría a productores y empresarios, facilitando su vinculación con el mercado laboral y promoviendo oportunidades.', 7, 36, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (214, 'Dignificar los espacios de la vivienda de las personas en situación de pobreza y reducir el hacinamiento habitacional en las zonas rural y urbana, a través de mecanismos de coordinación con los diferentes órdenes de gobierno para reforzar las acciones de mejoramiento y equipamiento de viviendas, especialmente en cuanto a piso firme, techo, muro y baño.', 1, 37, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (215, 'Brindar apoyos directos a hogares en condición de rezago social para garantizar los servicios básicos y complementarios de las viviendas, con el propósito de mejorar la calidad de vida de las familias en Campeche.', 2, 37, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (216, 'Gestionar el acceso a planes de financiamiento flexibles para la obtención de viviendas dignas y de bajo costo para la población sin acceso a créditos. madres solteras, jóvenes y grupos en situación de vulnerabilidad.', 3, 37, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (217, 'Promover el financiamiento de desarrollos habitacionales que utilicen materiales y tecnologías amigables con el ambiente, con el objetivo de reducir el consumo de energía eléctrica, emisión de CO2 y residuos contaminantes, y asegurando el cumplimiento de la normatividad de desarrollo sustentable.', 4, 37, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (218, 'Promover una estrategia de coordinación intergubernamental para la integración de un sistema de información y consulta de indicadores de evaluación de vivienda, lotes y monitoreo al desempeño urbano ambiental que aporten a la solución del problema habitacional del Estado.', 5, 37, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (219, 'Promover la coordinación de esfuerzos interinstitucionales para proporcionar certeza jurídica sobre la propiedad y posesión de la vivienda familiar, así como fomentar la regularización, ordenamiento y sostenibilidad de los asentamientos urbanos.', 6, 37, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (220, 'Establecer esquemas para identificar, desarrollar y retener talentos deportivos mediante exhibiciones de disciplinas deportivas convencionales y del deporte adaptado, del acompañamiento por equipos multidisciplinarios, y otorgamiento de becas  e incentivos.', 1, 38, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (221, 'Promover la activación física y la práctica deportiva en los municipios para niños, niñas, adolescentes, jóvenes, mujeres, personas con discapacidad, adultos mayores y organizaciones deportivas del sector público social y privado, utilizando la infraestructura existente, con el objetivo de fortalecer la cohesión y la paz social en los núcleos familiares.', 2, 38, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (222, 'Establecer convenios de coordinación con el sector educativo y las autoridades municipales para impulsar la práctica deportiva en las escuelas y centros de formación.', 3, 38, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (223, 'Promover una estrategia de colaboración interinstitucional para actualizar el censo de la infraestructura deportiva existente a nivel estatal y municipal, evaluando su estado físico y operativo con el fin de planificar su rehabilitación y mantenimiento.', 4, 38, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (224, 'Recuperar y crear espacios públicos para el deporte y la recreación en todo el Estado, a través de proyectos de participación comunitaria.', 5, 38, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (225, 'Proporcionar una atención integral, a las y los deportistas campechanos de alto rendimiento con miras a competencias y eventos regionales, nacionales e internacionales de corto, mediano y largo plazo.', 1, 39, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (226, 'Consolidar las capacidades del equipo multidisciplinario y entrenadores de las y los deportistas de alto rendimiento con un enfoque incluyente.', 2, 39, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (227, 'Gestionar infraestructura y equipamiento deportivo incluyente y de calidad para facilitar la práctica del deporte de alto rendimiento.', 3, 39, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (228, 'Diseñar esquemas financieros que sirvan como base para proporcionar estímulos a entrenadores y deportistas, especialmente a aquellos que ganen medallas en competencias de alto rendimiento.', 4, 39, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (229, 'Crear las alianzas regionales, nacionales e internacionales necesarias para el fomento del deporte de alta competencia y la atracción de encuentros deportivos de categoría regional, nacional e internacional.', 5, 39, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (230, 'Fortalecer las capacidades de los atletas de alto rendimiento mediante el intercambio de experiencia en instituciones y organismos nacionales e internacionales.', 6, 39, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (231, 'Desarrollar y promover una agenda cultural inclusiva y diversa, que fomente la participación de nuevos segmentos en actividades artísticas y culturales, con el objetivo de enriquecer la experiencia cultural y fortalecer la identidad comunitaria', 1, 40, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (232, 'Desarrollar propuestas culturales dirigidas específicamente a niñas, niños, adolescentes y jóvenes, que consideren y aborden de manera crítica las estructuras sociales, discursos arraigados y dinámicas que promueven el racismo, la discriminación y la violencia en Campeche, con el objetivo de promover la inclusión, la diversidad y el respeto a los derechos humanos a través de expresiones artísticas y culturales adecuadas para estas audiencias.', 2, 40, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (233, 'Fortalecer el sentido de pertenencia y orgullo hacia nuestras tradiciones, costumbres, saberes ancestrales, expresiones artísticas populares, así como nuestra riqueza natural y cultural, a través de programas y actividades que promuevan la valoración, difusión y preservación de nuestro patrimonio cultural, incentivando la participación activa de la comunidad en su conservación y transmisión a las futuras generaciones.', 3, 40, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (234, 'Visibilizar la aportación de la cultura maya viva a la identidad del Estado y rescatar sus prácticas comunitarias de gestión social y ambiental, promoviendo su valoración y preservación como parte integral del patrimonio cultural de Campeche.', 4, 40, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (235, 'Incentivar el uso democrático, armonioso y participativo del espacio público mediante la organización de eventos masivos culturalmente enriquecedores, que fomenten la convivencia comunitaria y la diversidad cultural en Campeche.', 5, 40, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (236, 'Rehabilitar, adaptar y mantener la infraestructura necesaria para ofertar los servicios culturales, dando prioridad a los centros culturales con enfoque a la atención y mejora de los centros culturales como espacios clave para el desarrollo y la promoción de actividades artísticas y culturales en Campeche.', 6, 40, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (237, 'Contribuir a la difusión, revalorización y protección del patrimonio cultural, urbano y arquitectónico del Estado con un enfoque inclusivo, promoviendo el uso y aprovechamiento de espacios residuales generados por el proceso de urbanización para actividades culturales y comunitarias que enriquezcan la identidad local y fomenten la participación ciudadana.', 7, 40, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (238, 'Desarrollar esquemas de difusión pertinentes a nivel local, nacional e internacional para cada uno de los servicios culturales ofrecidos, reconociendo a los públicos existentes, y utilizando tecnologías de la información y comunicación, para promover la participación y el acceso a la diversidad cultural del Estado.', 8, 40, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (239, 'Establecer políticas públicas de educación en materia artística y cultural mediante el fortalecimiento de los centros culturales y las escuelas de iniciación y profesionalización, promoviendo el acceso equitativo a la formación y el desarrollo de habilidades en las artes y la cultura.', 1, 41, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (240, 'Ofrecer programas de formación, exposición y apreciación artística en espacios escénicos para visibilizar las manifestaciones artísticas infantiles, juveniles y de las personas con discapacidad, promoviendo el desarrollo de talentos y la participación activa de las nuevas generaciones en el ámbito cultural.', 2, 41, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (241, 'Coadyuvar en la elaboración y gestión de proyectos artísticos y culturales de los pueblos originarios, respetando sus tradiciones y promoviendo el desarrollo autónomo de su identidad cultural y creativa.', 3, 41, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (242, 'Gestionar becas y otorgar estímulos para apoyar la educación artística y cultural, así como la creación, producción, difusión de las y los creadores, promotores y gestores culturales, fortaleciendo así el desarrollo y la diversidad cultural en el Estado.', 4, 41, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (243, 'Promover la coordinación entre los tres órdenes de gobierno y la construcción de alianzas nacionales e internacionales para la implementación de proyectos artísticos y culturales, así como el impulso de proyectos de coinversión en el desarrollo del Estado.', 5, 41, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (244, 'Fortalecer el intercambio de expresiones artísticas a través de la colaboración con creadores nacionales e internacionales, para potenciar el turismo cultural en el estado, promoviendo la diversidad cultural y la valoración del patrimonio artístico local.', 6, 41, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (245, 'Incentivar el diálogo e intercambio cultural con otras culturas originarias del país y del mundo, promoviendo la diversidad cultural, el respeto mutuo y el enriquecimiento de experiencias artísticas y tradiciones.', 7, 41, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (246, 'Fomentar y propiciar la constitución de empresas creativas y culturales, así como los espacios independientes, para el desarrollo sostenible del sector cultural y creativo.', 8, 41, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (247, 'Realizar programas permanentes de sensibilización, formación y capacitación dirigidas a servidores públicos y sociedad civil, para el fomento al respeto a los derechos humanos, la inclusión social, la perspectiva de género, la no violencia, la no discriminación, la interculturalidad, multiculturalidad, la diversidad sexual y la erradicación del adulto-centrismo, así como de los estereotipos sociales.', 1, 42, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (248, 'Implementar programas y acciones gubernamentales que aborden de manera específica e incluyente las necesidades de los grupos prioritarios en condición de vulnerabilidad social.', 2, 42, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (249, 'Promover la actualización y armonización de los instrumentos jurídicos y administrativos necesarios para garantizar el pleno ejercicio de los derechos humanos de las personas en situación de vulnerabilidad.', 3, 42, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (250, 'Brindar asesoría legal, de derechos humanos y psicológica gratuita especializada a los grupos prioritarios en situación de vulnerabilidad.', 4, 42, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (251, 'Fortalecer el registro e identificación de las personas en situación de calle y en proceso de reinserción social en libertad para focalizar la intervención gubernamental, facilitando la implementación de programas específicos dirigidos a estas poblaciones vulnerables.', 1, 43, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (252, 'Impulsar la creación o reforma de instrumentos jurídicos para contribuir a la protección y promoción de los derechos humanos de las personas en situación de calle y en proceso de reinserción social, asegurando marcos legales sólidos que garanticen sus derechos fundamentales y su inclusión social.', 2, 43, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (253, 'Implementar políticas públicas que atiendan las necesidades particulares de las personas en situación de calle y en proceso de reinserción social, promoviendo el acceso a servicios sociales, atención médica y programas de empleo para favorecer su inclusión y bienestar.', 3, 43, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (254, 'Implementar campañas de sensibilización social dirigidas a la comunidad en general para combatir la estigmatización, el rechazo, la exclusión y la violencia hacia las personas en situación de calle y en proceso de reinserción social, fomentando la empatía, el respeto y la solidaridad como principios fundamentales de convivencia.', 4, 43, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (255, 'Impulsar la transversalización de la perspectiva de género en todos los ciclos de las políticas públicas y garantizar la ejecución eficiente de un presupuesto público con perspectiva de género.', 1, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (256, 'Fortalecer las Unidades de Igualdad Sustantiva (UIS) de la administración pública a través de la dotación de sustento normativo e instrumentos administrativas.', 2, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (257, 'Monitorear el grado de cumplimiento de las acciones que fortalecen la igualdad entre mujeres y hombres.', 3, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (258, 'Reducir las brechas de desigualdad por razones de género, promoviendo los diversos servicios de prevención y atención a víctimas de violencia de género.', 4, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (259, 'Implementar medidas específicas para garantizar que al menos el 50% de los beneficiarios de programas sociales y servicios estatales sean mujeres, mediante el diseño y ejecución de acciones, proyectos y programas con enfoque en la igualdad de género.', 5, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (260, 'Diseñar y ejecutar mecanismos de colaboración interinstitucional con los tres órdenes de gobierno con el objetivo de fortalecer las capacidades, el desarrollo, bienestar igualitario, así como erradicar la violencia de género, con especial énfasis de las mujeres que habitan en asentamientos rurales y provenientes de pueblos originarios.', 6, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (261, 'Implementar instrumentos en materia de igualdad de género y no violencia, supervisado y monitoreado obligatoriamente a través de las unidades de igualdad sustantiva de las Entidades de Administración Pública Estatal.', 7, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (262, 'Fortalecer la coordinación interinstitucional, entre órdenes de gobierno y la sociedad civil para fortalecer, especializar, profesionalizar y hacer accesibles los servicios de atención jurídica y psicológica, asesoramiento y acompañamiento a víctimas de violencia de género en el Estado, con especial énfasis a mujeres indígenas o pertenecientes a grupos marginados.', 8, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (263, 'Implementar y promover programas de capacitación obligatoria en materia de: Igualdad de género, derechos humanos, no violencia y diversidad, promoviendo la adopción de una cultura organizacional que garantice la protección y respeto a los derechos humanos, la conciliación entre el trabajo y la vida personal de las y los servidores públicos, la difusión del Protocolo de acoso y hostigamiento sexual de la APE y entornos laborales libres de violencia', 9, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (264, 'Impulsar campañas informativas y de sensibilización que fomenten la participación social en actividades dirigidas a la reducción y erradicación de la violencia y la discriminación.', 10, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (265, 'Promover el establecimiento de refugios seguros y líneas de atención especializadas para mujeres víctimas de violencia.', 11, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (266, 'Impulsar la Paridad de Género en los niveles de toma de decisiones de la Administración Pública Estatal.', 12, 44, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (267, 'Impulsar programas y acciones que fomenten el desarrollo profesional, el acceso a las nuevas tecnologías de la información y comunicación, el fortalecimiento de capacidades, la empleabilidad y el emprendimiento de las juventudes.', 1, 45, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (268, 'Promover en coordinación con el sector de la salud, la cultura y el deporte, el acceso de las juventudes a la salud física y mental, así como a la manifestación de expresiones artísticas, a través de un modelo de atención integral basado en perspectiva de género, nuevas masculinidades, derechos humanos, diversidad sexo afectiva y reducción de riesgos y daños.', 2, 45, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (269, 'Establecer campañas informativas y de sensibilización permanentes para abordar adicciones, problemas psicoemocionales, fomento de valores y la erradicación de entornos de violencia en beneficio de las juventudes.', 3, 45, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (270, 'Colaborar en la organización de eventos formativos, recreativos, culturales, de trasferencia de conocimientos y emprendimiento que fomenten el talento, la creatividad, el reconocimiento, el valor, las capacidades y la integración de las juventudes al proceso de desarrollo del estado.', 4, 45, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (271, 'Propiciar espacios donde las juventudes como agentes de cambio social, sean incluidas en el dialogo, interacción y desarrollo de las políticas públicas en materia de juventud, así como en la construcción e implementación de soluciones sostenibles a problemas públicos en beneficio de sus comunidades.', 5, 45, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (272, 'Fomentar la creación de alianzas público-privadas, a nivel local, nacional e internacional para construir oportunidades de vida y bienestar de las y los jóvenes campechanos.', 6, 45, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (273, 'Implementar acciones, programas y/o políticas públicas que promuevan la protección e igualdad de derechos de las personas adultas mayores y personas con discapacidad, para su inclusión en los ámbitos económico, social y educativo.', 1, 46, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (274, 'Propiciar acciones para mejorar el bienestar físico, nutricional, psíquico, emocional y/o social de las personas adultas mayores y las personas con discapacidad mediante la cobertura de servicios integrales que aborden sus necesidades de manera holística.', 2, 46, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (275, 'Impulsar la coordinación intergubernamental y la promoción de alianzas público-privadas para generar entornos inclusivos y las condiciones necesarias para que garanticen la accesibilidad y la movilidad segura de las personas con discapacidad y las personas adultas mayores.', 3, 46, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
