INSERT INTO `cat_action_lines` VALUES (277, 'Concientizar acerca del cuidado, protección, reconocimiento, respeto y empatía hacia las personas con discapacidad y las personas adultas mayores, fomentando una cultura de inclusión y sensibilización en la sociedad.', 5, 46, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (278, 'Promover la presencia de intérpretes de lenguaje de señas en las instituciones para mejorar la atención y comunicación, facilitando el acceso a los servicios y promoviendo la inclusión de las personas con discapacidad auditiva.', 6, 46, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
