INSERT INTO `cat_action_lines` VALUES (280, 'Reducir el porcentaje de niños, niñas y adolescentes en situación de violencia, desigualdad, pobreza y vulnerabilidad, mediante la implementación de acciones y políticas públicas específicas y acciones de sensibilización con enfoque transversal.', 1, 47, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
