INSERT INTO `cat_action_lines` VALUES (285, 'Impulsar el otorgamiento de apoyos, bienes y servicios en los sectores social y privado, a nivel municipal, estatal, nacional e internacional, para fortalecer los Centros de Asistencia Social en beneficio de las niñas, niños adolescentes en el estado.', 6, 47, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
