INSERT INTO `cat_action_lines` VALUES (288, 'Integrar una agenda colaborativa de la diversidad y la inclusión con enfoque de derechos humanos, para incorporar esta perspectiva en los temas económicos, de salud, sociales y de seguridad en beneficio de la Comunidad LGBTTTQI+.', 3, 48, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
