INSERT INTO `cat_action_lines` VALUES (292, 'Impulsar la perspectiva de género en la asignación de apoyos y recursos de los programas públicos dirigidos a la población indígena para promover la equidad y la inclusión de las mujeres indígenas en el acceso a estos beneficios.', 1, 49, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
