INSERT INTO `cat_action_lines` VALUES (295, 'Promover la perspectiva de género en la asignación de apoyos y recursos de los programas públicos dirigidos a la población indígena para promover la equidad y la inclusión de las mujeres indígenas en el acceso a estos beneficios.', 4, 49, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (296, 'Realizar campañas de respeto a los derechos de las personas maya hablantes y demás grupos indígenas existentes en el estado, promoviendo el reconocimiento de su identidad cultural y la sensibilización sobre sus derechos humanos fundamentales.', 5, 49, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
