INSERT INTO `cat_action_lines` VALUES (337, 'Promover acciones para la construcción, rehabilitación de la infraestructura o equipamiento pesquero y acuícola, con el fin de procurar la productividad y competitividad del sector', 3, 60, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (338, 'Realizar acciones para promover el desarrollo de proyectos en materia de pesca y acuacultura, facilitando el acceso a recursos, tecnología y conocimientos necesarios para impulsar el crecimiento sostenible del sector.', 4, 60, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
