INSERT INTO `cat_action_lines` VALUES (340, 'Fomentar el consumo de productos pesqueros y acuícolas, resaltando su alto valor nutricional, con el fin de asegurar la alimentación y el bienestar de la población', 2, 61, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
