INSERT INTO `cat_action_lines` VALUES (421, 'Impulsar una agenda de desarrollo productivo sustentable estableciendo criterios ambientales para su regulación en colaboración con instituciones, organizaciones, sectores y sociedad civil.', 2, 83, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
