INSERT INTO `cat_action_lines` VALUES (423, 'Desarrollar acciones en materia de cambio climático para la mitigación de sus impactos y la adopción de estrategias de adaptación, con la participación activa de la sociedad en general.', 1, 84, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (424, 'Implementar la estrategia de control y reducción de emisiones de gases y compuestos de efecto invernadero, a través de acciones de monitoreo, reporte y verificación.', 2, 84, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (425, 'Atraer inversiones para el desarrollo tecnológico de energías renovables y no renovables.', 1, 85, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (426, 'Fomentar la investigación y capacitación en torno a las energías renovables.', 2, 85, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (427, 'Generar convenios de colaboración con entidades educativas, gubernamentales y privadas para la atracción de inversiones y la transferencia de conocimientos.', 3, 85, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (428, 'Favorecer la implementación de energías renovables en el gobierno estatal.', 4, 85, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (429, 'Promover con las autoridades competentes, la inclusión en la evaluación y autorización de proyectos de generación de energías renovables y no renovables.', 5, 85, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (430, 'Divulgar las formas de generación de energías no renovables y renovables.', 6, 85, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (431, 'Fomentar la cultura energética para sensibilizar a la sociedad sobre su beneficio e impacto positivo que se obtiene al utilizarlas.', 7, 85, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (432, 'Promover la estrategia de ordenamiento territorial, ecológico, comunitario y participativo en colaboración con los tres órdenes de gobierno, la academia, el sector privado y la sociedad civil, acorde con los criterios de cada sector para la regulación del uso de suelo y actividades productivas.', 1, 86, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (433, 'Coadyuvar en la elaboración y seguimiento de los diversos intrumentos de planeación urbana y ordenamiento territorial para mejorar la calidad de vida y la productividad de los habitantes del Estado de Campeche.', 1, 87, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (434, 'Impulsar la movilidad y accesibilidad a través de instrumentos normativos integrales en coordinación con las instituciones y sectores de la sociedad. ', 2, 87, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (435, 'Diseñar y desarrollar infraestructura y equipamiento inclusivo para mejorar la accesibilidad de los usuarios.', 1, 88, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (436, 'Armonizar los espacios públicos y privados para renovar la imagen urbana en beneficio de los centros de población.', 2, 88, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (437, 'Preservar la inversión en materia de obra pública, desarrollo urbano y territorial para contribuir al desarrollo sostenible del Estado.', 3, 88, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (438, 'Promover la accesibilidad equitativa de servicios públicos indispensables para coadyuvar en la reducción de las desigualdadades entre los sectores sociales.', 4, 88, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (439, 'Ejecutar obras de rehabilitación, conservación y mantenimiento, en edificios públicos para optimizar los procesos administrativos y la atención a los ciudadanos.', 5, 88, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (440, 'Gestionar y realizar acciones y obras de infraestructura para coadyuvar a la protección, preservación, rehabilitación, restauración y conservación de los bienes muebles, inmuebles y documentales históricos que componen el patrimonio cultural y biocultural del Estado.', 6, 88, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (441, 'Impulsar proyectos para ampliar la infraestructura eléctrica en todo el territorio estatal.', 1, 89, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (442, 'Gestionar e impulsar acciones ante la Comisión Federal de Electricidad para que el suministro eléctrico sea confiable y de calidad.', 2, 89, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (443, 'Impulsar la movilidad y accesibilidad sostenible, sustentable e incluyente para un tránsito seguro y confortable de los usuarios.', 1, 90, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (444, 'Desarrollar una infraestructura vial alternativa para lograr localidades accesibles, dinámicas y con mejor calidad de vida y habitabilidad para los ciudadanos del Estado.', 2, 90, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (445, 'Fomentar una ingeniería de transporte y señalamiento vial para regular y canalizar el tránsito de vehículos y peatones de manera eficiente.', 3, 90, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (446, 'Innovar y modernizar la interconexión estatal para impulsar el desarrollo productivo de las localidades y disminuir los tiempos de traslados de sus bienes y servicios.', 4, 90, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (447, 'Incrementar la cobertura de los servicios de agua y saneamiento mediante la construcción y dotación de infraestructura hidráulica con énfasis en zonas de atención prioritaria urbanas y rurales.', 1, 91, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (448, 'Gestionar programas de mejora, mantenimiento y modernización de activos, bienes muebles e inmuebles afectos a la prestación de los servicios públicos para extender la vida útil y asegurar la operación en el largo plazo de los sistemas de agua potable y saneamiento.', 2, 91, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (449, 'Fomentar esquemas de asociación e inversión pública, privada y social para el desarrollo de proyectos ejecutivos,  construcción, mantenimiento, operación y administración de infraestructura hidráulica para la prestación de los servicios públicos.', 3, 91, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (450, 'Realizar ajustes al marco regulatorio para garantizar la seguridad hídrica, el aprovechamiento sustentable y la gobernanza del agua.', 1, 92, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (451, 'Apoyar el desarrollo de capacidades técnicas, administrativas y de gestión del personal de los organismos operadores municipales y comités comunitarios para la prestación eficiente de los servicios públicos de agua y saneamiento, garantizando su continuidad y viabilidad financiera.', 2, 92, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_action_lines` VALUES (452, 'Generar una cultura del agua que fomente la concientizaión social  sobre el consumo responsable, el aprovechamento sustentable,  la proteccion del ciclo hidrológico y la prevención de riesgos hidrometeorológicos.', 3, 92, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
