INSERT INTO `cat_i_concepts` VALUES (1, 'Total de denuncias, querellas y otras notificaciones hechas del conocimiento del ministerio público durante el año, es decir, del 01 de enero al 31 de diciembre', 1);
INSERT INTO `cat_i_concepts` VALUES (2, 'Carpetas de investigación iniciadas durante el año, es decir, del 01 de enero al 31 de diciembre', 1);
INSERT INTO `cat_i_concepts` VALUES (3, 'Tipo de atención que recibieron las denuncias o querellas que fueron atendidas de alguna forma distinta a la apertura de una carpeta de investigación durante el año, es decir, del 01 de enero al 31 de diciembre', 1);
INSERT INTO `cat_i_concepts` VALUES (4, 'Forma de inicio de las carpetas de investigación iniciadas durante el año, es decir, del 01 de enero al 31 de diciembre', 1);
INSERT INTO `cat_i_concepts` VALUES (5, 'Determinaciones ministeriales emitidas durante el año (con independencia de la fecha de inicio de la carpeta de investigación)', 1);
INSERT INTO `cat_i_concepts` VALUES (6, 'Total de carpetas de investigación en trámite, es decir, que no recibieron algún tipo de determinación ministerial, al cierre del año (con independencia de la fecha de inicio de la carpeta de investigación)', 1);
INSERT INTO `cat_i_concepts` VALUES (7, 'Total de carpetas de investigación reingresadas (reactivadas) del archivo temporal durante el año (con independencia de la fecha de inicio de la carpeta de investigación)', 1);
INSERT INTO `cat_i_concepts` VALUES (8, 'Total de personas respecto de las cuales el ministerio público ejerció la acción penal (con independencia de la fecha de inicio de la carpeta de investigación)', 1);
INSERT INTO `cat_i_concepts` VALUES (9, 'Total de carpetas de investigación en las cuales se ejerció la acción penal y su resultado', 1);
INSERT INTO `cat_i_concepts` VALUES (10, 'Tipo de medidas cautelares solicitadas por el ministerio público durante el año (con independencia de la fecha de inicio de los procedimientos registrados en las carpetas de investigación)', 1);
INSERT INTO `cat_i_concepts` VALUES (11, 'Total de medidas de protección solicitadas durante el año al ministerio público del fuero común durante el año (con independencia de la fecha de inicio de los procedimientos registrados en las carpetas de investigación)', 1);
INSERT INTO `cat_i_concepts` VALUES (12, 'Total de carpetas de investigación que fueron derivadas por el ministerio público al órgano o unidad especializada en Mecanismos Alternativos de Solución de Controversias (MASC) en materia penal, durante el año (con independencia de la fecha de inicio de la carpeta de investigación)', 1);
INSERT INTO `cat_i_concepts` VALUES (13, 'Número de acuerdos reparatorios aprobados por el ministerio público al cierre del año (con independencia de la fecha de inicio de la carpeta de investigación) y forma de cumplimiento', 1);
INSERT INTO `cat_i_concepts` VALUES (14, 'Número de acuerdos reparatorios incumplidos al cierre del año según tipo de mecanismo alternativo empleado (con independencia de la fecha de inicio de la carpeta de investigación o de la fecha de celebración del acuerdo reparatorio)', 1);
