INSERT INTO `cat_narrative_strategies` VALUES (1, 'Promover un gobierno cercano a la gente y eficaz con su desempeño.', 1, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (2, 'Brindar asesoría técnica y capacitación a los gobiernos municipales.', 2, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (3, 'Ampliar la cobertura, difusión de información y comunicación social.', 3, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (4, 'Resguardar la memoria histórica institucional y social del Estado y de sus Municipios.', 4, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (5, 'Promover la paz laboral, a través del funcionamiento de los órganos de justicia laboral administrativa, procurando lograr una solución eficaz en la aplicación de la justicia laboral.', 5, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (6, 'Implementar una gestión eficiente del ingreso', 1, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (7, 'Promover el uso responsable de los recursos', 2, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (8, 'Ejercer y controlar de manera responsable, eficiente y transparente los recursos materiales, patrimoniales y de servicios, así como los recursos humanos, pensiones y prestaciones sociales.', 3, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (9, 'Implementar mecanismos que contribuyan a una rendición de cuentas claras y transparentes.', 1, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (10, 'Contar con un marco jurídico de libre acceso para las y los ciudadanos.', 2, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (11, 'Implementar acciones para prevenir, combatir y sancionar la corrupción', 1, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (12, 'Implementar una planeación estrátegica con enfoque internacional', 1, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (13, 'Promover la modernización e innovación administrativa', 2, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (14, 'Simplificar trámites, servicios y regulaciones.', 3, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (15, 'Establecer un sistema integral y modular de Información Estadistica, Geográfica y Catastral', 4, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (16, 'Fortalecer el gobierno digital, abierto y transparente', 5, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (17, 'Disponer de un sistema de transporte público que fomente y potencie el desarrollo económico y social en el Estado', 1, 6, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (18, 'Fortalecer, promover, difundir y garantizar el respeto de los derechos humanos en la entidad', 1, 7, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (19, 'Promover el fortalecimiento de la seguridad ciudadana.', 1, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (20, 'Activar los centros de estudios de seguridad pública en condiciones óptimas y con servicios educativos de calidad.', 2, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (21, 'Garantizar mediante los procesos de control de confianza el desempeño de los elementos de seguridad', 3, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (22, 'Prevenir la delincuencia.', 4, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (23, 'Implementar un programa estatal de prevención social del delito con la participación ciudadana ', 5, 8, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (24, 'Promover la impartición y procuración de justicia.', 1, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (25, 'Impulsar y garantizar un sistema de defensoría pública y de calidad en el Estado de Campeche', 2, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (26, 'Fortalecer la búsqueda y localización de personas desaparecidas.', 3, 9, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (27, 'Fortalecer el sistema penitenciario en congruencia con el proceso de justicia penal para un óptimo servicio encausado a la reinserción social.', 1, 10, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (28, 'Establecer la prevención como eje fundamental de la reducción del riesgo de desastre.', 1, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (29, 'Mejorar la respuesta a emergencias y desastres para disminuir su impacto.', 2, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (30, 'Fortalecer mecanismos financieros de riesgos y el marco normativo de protección civil.', 3, 11, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (31, 'Promover la coordinación interinstitucional y con los tres órdenes de gobierno para el fortalecimiento, priorización, focalización y complementariedad de los programas, bienes y servicios para el bienestar, el desarrollo social, la cohesión social y el co', 1, 12, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (32, 'Consolidar los servicios de salud con un enfoque prioritario en la prevención y promoción de estilos de vida saludables, mejorando la vigilancia epidemiológica y optimizando el control de enfermedades, para garantizar una cobertura amplia y equitativa en ', 1, 13, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (33, 'Desarrollar e implementar acciones para promover, regular, controlar y vigilar de manera efectiva los riesgos sanitarios, asegurando la protección de la salud pública.', 2, 13, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (34, 'Impulsar la cobertura y acceso universal a una educación de calidad, inclusiva y basada en los derechos humanos, priorizando la atención a la población en situación de vulnerabilidad, analfabetismo y rezago educativo.', 1, 14, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (35, 'Fortalecer la calidad, pertinencia, excelencia e integralidad de la oferta educativa en todos los niveles mediante acciones dirigidas a mejorar los planes de estudio, la formación docente, los recursos educativos y las infraestructuras escolares.', 2, 14, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (36, 'Fortalecer las capacidades sociales para el desarrollo, el bienestar y la cohesión social mediante la vinculación estratégica del Sistema Educativo con la Política de Desarrollo Económico del Estado, promoviendo la formación integral de los estudiantes y ', 3, 14, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (37, 'Establecer mecanismos de financiamiento accesibles y de coordinación intergubernamental en beneficio de las personas y las familias que enfrentan mayores condiciones de rezago y vulnerabilidad, para facilitar la adquisición, construcción, ampliación y mej', 1, 15, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (38, 'Impulsar la cultura física, la recreación y el deporte mediante políticas públicas que promuevan el fomento deportivo, la detección y apoyo de talentos, así como al fortalecimiento y recuperación de infraestructura deportiva de calidad en el Estado.', 1, 16, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (39, 'Promover la economía deportiva responsable y profesional como una oportunidad de desarrollo para Campeche, con proyección regional, nacional e internacional.', 2, 16, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (40, 'Implementar políticas públicas incluyentes que favorezcan la producción, fomento, desarrollo, promoción, difusión, preservación y reconocimiento de todas las manifestaciones artísticas y culturales, para fortalecer la diversidad cultural y el acceso equit', 1, 17, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (41, 'Impulsar la profesionalización de artistas, promotores, gestores y trabajadores de la cultura mediante programas de formación, capacitación, asesoría y acceso a recursos que fortalezcan sus habilidades, conocimientos y oportunidades laborales en el sector', 2, 17, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (42, 'Priorizar la intervención pública y la focalización en la prestación igualitaria de bienes y servicios a través de políticas públicas vinculantes y con alcance transversal en beneficio de las personas y grupos prioritarios, eliminando cualquier práctica d', 1, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (43, 'Promover acciones de coordinación interinstitucional para la atención puntual e inclusión social de las personas en situación de calle y en proceso de reinserción social, garantizando la protección efectiva de sus derechos humanos y facilitando su integra', 2, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (44, 'Garantizar el respeto, acceso, integración y participación igualitaria de las mujeres en todos los sectores, mediante políticas públicas vinculantes y de alcance transversal, con el objetivo de eliminar cualquier práctica discriminatoria y la violencia de', 3, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (45, 'Implementar programas y acciones interinstitucionales con perspectiva transversal para contribuir al desarrollo integral de las juventudes, construyendo oportunidades y capacidades que promuevan su desarrollo y bienestar en atención a sus derechos sociale', 4, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (46, 'Contribuir al acceso a una vida digna y a la integración social de las personas adultas mayores y personas con alguna discapacidad, en respeto a sus derechos esenciales, mediante la implementación de programas sociales complementarios y diversificados.', 5, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (47, 'Fortalecer el desarrollo integral de niñas, niños y adolescentes, priorizando su Interés Superior, con acciones que promuevan la protección y garanticen la progresividad de sus derechos.', 6, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (48, 'Proteger y respetar los derechos humanos, la seguridad y libertad de expresión de género y afecto de la Comunidad LGBTTTQI+, mediante programas inclusivos que garanticen su acceso a oportunidades igualitarias de desarrollo y bienestar.', 7, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (49, 'Impulsar un modelo de intervención integral comunitaria para reducir las carencias y brechas sociales de los pueblos originarios, respetando a sus derechos humanos, tradiciones, usos y costumbres, con el objetivo de mejorar su calidad de vida y promover s', 8, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (50, 'Articular el diseño de políticas públicas que promuevan la atención integral, respeten los derechos humanos y fomenten la igualdad sustantiva de las personas migrantes. ', 9, 18, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (51, 'Impulsar la Gobernanza, la construcción de Alianzas Multiactor público-privadas, para fortalecer la participación y compromiso público en las acciones de desarrollo social y comunitario.', 1, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (52, 'Promover el bienestar y desarrollo integral de las familias para fortalecer la cohesión y la recuperación del tejido social.', 2, 19, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (53, 'Fomentar la industrialización del Estado de Campeche, que permita elevar la competitividad de los sectores productivos. ', 1, 20, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_narrative_strategies` VALUES (54, 'Fomentar la inversión privada local, nacional y extranjera; a través de la promoción de las ventajas comparativas y competitivas; que contribuyan al crecimiento del Producto Interno Bruto del Estado', 2, 20, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
