INSERT INTO `cat_objectives` VALUES (1, 'Fomentar y robustecer la política interior del estado para tener un gobierno sensible y de todos.', 1, 1, NULL, '2025-03-05 21:30:55', '2025-03-05 21:30:55');
INSERT INTO `cat_objectives` VALUES (2, 'Recaudar los ingresos del Estado y ejercer el presupuesto de egresos de manera eficaz, eficiente, austera, transparente y orientada a resultados.', 2, 1, NULL, '2025-03-05 21:30:55', '2025-03-05 21:30:55');
INSERT INTO `cat_objectives` VALUES (3, 'Mejorar el desempeño del servicio público a través de mecanismos de control interno, auditorías, fiscalización, investigación y responsabilidades administrativas; brindando a la ciudadanía una rendición de cuentas clara, transparente, eficiente, eficaz y honesta', 3, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (4, 'Combatir a la corrupción, involucrando a la sociedad en las gestiones gubernamentales y la aplicación de los recursos públicos, concientizando a los servidores públicos sobre la importancia de la ética en su actuar.', 4, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (5, 'Mejorar la eficiencia y eficacia gubernamental a través de la mejora continua de la gestión pública para el cumplimiento de los objetivos del desarrollo estatal.', 5, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (6, 'Impulsar un modelo que garantice el desplazamiento de los ciudadanos del estado, con eficiencia, accesibilidad y seguridad, que contenga los conceptos de movilidad sustentable, sostenible e incluyente. ', 6, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (7, 'Consolidar una cultura de derechos humanos en la Entidad que garantice su respeto, protección, promoción y garantía en beneficio de todas las personas.', 7, 1, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (8, 'Fortalecer las instituciones de seguridad pública.', 1, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (9, 'Impartir y procurar la justicia con enfoque ciudadano', 2, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (10, 'Consolidar y mejorar el sistema penitenciario.', 3, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (11, 'Proteger la vida y la integridad de la población aplicando la gestión integral de riesgo de desastres.', 4, 2, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (12, 'Contribuir al bienestar, a la igualdad social y al cumplimiento de derechos humanos de la población en el Estado, a través de acciones que incidan en la disminución de la pobreza, la marginación y el rezago social, dando prioridad a la niñez, a las juventudes, las mujeres, los adultos mayores, las personas con discapacidad, los pueblos originarios, las personas de la Comunidad LGBTTTQI+ y aquellos grupos que se encuentran en situación de vulnerabilidad.', 1, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (13, 'Garantizar acceso universal y gratuito a los servicios de salud de calidad en el Estado, respetando los usos y costumbres de la población, fomentando la equidad de género y salvaguardando los derechos humanos de la ciudadanía.', 2, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (14, 'Consolidar el Sistema Educativo integral, de calidad, accesible e incluyente en todos los niveles, priorizando las infancias, las juventudes, las personas con discapacidad, los pueblos originarios y la población con altos niveles de rezago social en la entidad', 3, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (15, 'Mejorar las condiciones de bienestar en los hogares más vulnerables del Estado, reduciendo el rezago en el acceso a una vivienda adecuada.', 4, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (16, 'Implementar programas y acciones que contribuyan a garantizar el derecho a la cultura física y al deporte, contribuyendo así al mejoramiento de la salud y el bienestar de las personas y las familias.', 5, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (17, 'Contribuir al bienestar de las personas y las familias, promoviendo la cohesión social y la construcción de paz, mediante el fortalecimiento, fomento y acceso inclusivo a la cultura y las artes en el Estado.', 6, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (18, 'Promover la construcción de las condiciones y oportunidades de desarrollo integral e inclusivo de las niñas, niños, adolescentes, las juventudes, las mujeres, los adultos mayores, las personas con discapacidad, las personas migrantes, los pueblos originarios, las personas en situación de calle, en proceso de reinserción social, las y los integrantes de la Comunidad LGBTTTQI+ y grupos prioritarios en la entidad, fortaleciendo sus capacidades y garantizando el reconocimiento y protección de sus derechos fundamentales.', 7, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (19, 'Fortalecer la cohesión social, el sentido de pertenencia e identidad colectiva, mediante el análisis y enfoque de las dinámicas comunitarias, con el propósito de potenciar la solidaridad, la participación y el desarrollo comunitario de manera integral, igualitaria, sostenible y corresponsable.', 8, 3, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (20, 'Generar una política industrial sostenible que permita contribuir al Producto Interno Bruto del Estado. ', 1, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (21, 'Incrementar la rentabilidad del campo, con un enfoque de producción y productividad sustentable, para lograr el desarrollo agropecuario sostenible del Estado y revertir el abandono en el que se encuentran las familias rurales', 2, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (22, 'Contribuir al incremento de la producción pesquera y acuícola para apoyar la suficiencia alimentaria y nutricional del estado de Campeche', 3, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (23, 'Impulsar el turismo en el Estado de Campeche como motor del desarrollo económico, en coordinación con el sector empresarial, académico y social', 4, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (24, 'Impulsar una política que coadyuve a generar relaciones comerciales hacia las micro, pequeñas y medianas empresas que les permita integrarse a las cadenas productivas locales, regionales, nacionales e internacionales, así como fortalecer al sector servicios del estado a través de la creación de sinergias entre los actores económicos', 5, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (25, 'Contribuir al crecimiento económico y al mejoramiento de la calidad de vida de la población del estado, de acuerdo con los principios de sostenibilidad', 6, 4, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (26, 'Garantizar el acceso a la justicia ambiental, el cumplimiento de la normatividad y el respeto a los derechos ambientales de las y los ciudadanos.', 1, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (27, 'Conservar y restaurar los ecosistemas naturales del estado y sus especies nativas, así como los servicios ambientales que generan.', 2, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (28, 'Brindar protección al medio ambiente como derecho humano a un ambiente sano y seguro, significando el principio del desarrollo y progreso sostenible en la lucha contra el cambio climático, el fomento a la cultura ambiental y el impulso de energías renovables.', 3, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (29, 'Establecer una gestión, ocupación y aprovechamiento integral, participativo, inclusivo y sustentable del territorio como herramienta de planeación para el desarrollo sostenible del estado.', 4, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (30, 'Promover una gestión territorial participativa y consciente con el propósito de fomentar el desarrollo sostenible y sustentable del estado.', 5, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (31, 'Democratizar la gestión de servicios públicos esenciales, infraestructura y equipamiento con el fin de promover el bienestar integral de los campechanos.', 6, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (32, 'Construir un Estado accesible e interconectado con el objeto de facilitar un adecuado desplazamiento y encadenamiento socioeconómico', 7, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
INSERT INTO `cat_objectives` VALUES (33, 'Propiciar la gestión integral de los recursos hídricos para garantizar el derecho al agua y al saneamiento, la seguridad hídrica y la sostenibilidad de los servicios públicos.', 8, 5, NULL, '2025-03-05 21:30:56', '2025-03-05 21:30:56');
